import logging
import os
import re
import time
from contextlib import contextmanager
from functools import wraps
from typing import Dict, List, Optional, TextIO, Tuple

import psutil  # type: ignore
from psutil import STATUS_ZOMBIE
from ute_common_abstract_core.message import Message  # type: ignore
from ute_fsmaccess import ute_fsmaccess  # type: ignore

from taf.ul.sbts.pmi_ticket_collector.settings import SSH_FHD_PATH
from taf.ul.sbts.pmi_ticket_collector.tunnel import SSHTunnelError


def timer(fun):
    @wraps(fun)
    def _inner(*args, **kwargs):
        start = time.time()
        ret = fun(*args, **kwargs)
        args[0]._logger.debug(f"{fun.__name__} finished in {round(time.time() - start, 2)}s")
        return ret

    return _inner


@contextmanager
def gnb_access(logger: logging.Logger, gnb_data: Dict[str, str], remote_host: str = "127.0.0.1"):
    ute_fsmaccess_instance = ute_fsmaccess()
    host = gnb_data["cu_ip"]
    try:
        logger.debug(f"SETUP START: ENB_ACCESS: [{host}, {remote_host}]")
        ute_fsmaccess_instance.setup_enb_fsm_access(host=host, remote_host=remote_host, retry_timeout=15)
        logger.debug(f"SETUP DONE: ENB_ACCESS: [{host}, {remote_host}]")
        yield ute_fsmaccess_instance
    finally:
        try:
            logger.debug(f"TEARDOWN START: ENB_ACCESS: [{host}, {remote_host}]")
            ute_fsmaccess_instance.teardown_enb_fsm_access()
            logger.debug(f"TEARDOWN DONE: ENB_ACCESS: [{host}, {remote_host}]")
        except Exception as exc:
            logger.warning(exc)


def parse_counters_to_check(pmi_counters: Tuple[str, ...]) -> Dict[str, Dict[str, str]]:
    counters = {}
    counter_regexp = re.compile(r"(==|!=|<=|>=|>|<|\beq\b|\bne\b|\ble\b|\bge\b|\bgt\b|\blt\b)")
    for pmi_counter in pmi_counters:
        match = counter_regexp.split(pmi_counter)
        if len(match) == 3:
            counter, operator, value = (x.strip() for x in match)
            counters[counter] = {"operator": operator, "value": value}
        else:
            raise ValueError(
                f"Not recognised PM Counter '{pmi_counter}'. Available format: <name><operator><value>, "
                "e.g. M55113C00501 == 1. Available names: dev value, M* value, Name. "
                "Available operators: ==, <, >, <=, >=, !=, eq, ne, le, ge, gt, lt"
            )
    return counters


def kill_all_processes_with_name(proc_name: str, logger: logging.Logger):
    for proc in (_proc for _proc in psutil.process_iter() if _proc.status() != STATUS_ZOMBIE):
        cmdline = proc.cmdline()
        if proc_name in " ".join(cmdline):
            logger.debug(f"Found process: {proc.pid} {cmdline} {proc}")
            proc.terminate()
            time.sleep(0.1)
            if not proc.is_running():
                continue
            else:
                proc.kill()
                time.sleep(0.1)
            if not proc.is_running():
                continue
            else:
                logger.warning("Couldn't kill process. Something might not work properly.")


def ssh_tunnels_checker(fun):
    @wraps(fun)
    def _inner(*args, **kwargs):
        self = args[0]
        ssh_watcher_present = hasattr(self, "_ssh_watcher")
        if (ssh_watcher_present and not self._ssh_watcher.ssh_broken) or not ssh_watcher_present:
            return fun(*args, **kwargs)
        else:
            self._logger.error("SSH Tunnel broken.")
            raise SSHTunnelError("SSH Tunnel broken")

    return _inner


def remove_ssh_files() -> None:
    for file in os.listdir("/tmp/"):
        if file.startswith("pmi_ticket_") and file != "pmi_ticket_ssh_fhd.log":
            try:
                os.remove(os.path.join("/tmp", file))
            except FileNotFoundError:
                pass


def open_ssh_fhd(logger: logging.Logger) -> Optional[TextIO]:
    ssh_fhd = None
    try:
        ssh_fhd = open(SSH_FHD_PATH, "a")
    except Exception as err:
        logger.debug(err, exc_info=True)
    return ssh_fhd


def close_ssh_fhd(ssh_fhd) -> None:
    if ssh_fhd:
        ssh_fhd.close()


def add_to_messages(messages: List[Message], data: Message) -> None:
    messages.append(data)
